 "content": "def transform(grid):
    """Tile the pattern 3 by 2, reflecting across tile boundaries."""
    h, w = len(grid), len(grid[0])
    out = []
    for tile_row in range(3):
        for r in range(h):
            source_r = h - 1 - r if tile_row % 2 == 0 else r
            row = []
            for tile_col in range(2):
                for c in range(w):
                    source_c = w - 1 - c if tile_col == 0 else c
                    row.append(grid[source_r][source_c])
            out.append(row)
    return out
